// High-quality reconstruction of small opaque two-ink antialiased artwork.
// Models are accepted from source pixels only; no reference vectors are inputs.
use std::collections::{HashMap,VecDeque};
use std::fmt::Write;
type P=[f64;2];
#[derive(Clone)]pub struct Plan{pub mask:Vec<u8>,pub w:usize,pub h:usize,pub rings:Vec<[f64;8]>,pub stars:Vec<[f64;5]>,pub inks:Vec<[u8;3]>}
fn sd(p:&[f64],x:f64,y:f64)->f64{let u=(x-p[0])/p[2];let v=(y-p[1])/p[3];let r=(u*u+v*v+1e-14).sqrt();(r-1.)/((u/p[2]).powi(2)+(v/p[3]).powi(2)+1e-14).sqrt()}
fn inside(p:&[f64],x:f64,y:f64)->f64{let d=sd(p,x,y);if d>0.5{0.}else if d< -0.5{1.}else{1./(1.+(d*20.).exp())}}
fn optimize<F:Fn(&[f64])->f64>(mut p:Vec<f64>,steps:Vec<f64>,bounds:Vec<f64>,cost:F)->(Vec<f64>,f64){let initial=p.clone();let mut best=cost(&p);let mut step=1.;for _ in 0..100{let mut changed=false;for j in 0..p.len(){for dir in [-1.,1.]{let mut q=p.clone();q[j]+=dir*steps[j]*step;if (q[j]-initial[j]).abs()>bounds[j]{continue;}let e=cost(&q);if e<best{p=q;best=e;changed=true;}}}if !changed{step*=0.5;}if step<0.002{break;}}(p,best)}
fn ellipse(points:&[P])->Option<([f64;4],f64)>{let mut lo=[f64::INFINITY;2];let mut hi=[f64::NEG_INFINITY;2];for p in points{for j in 0..2{lo[j]=lo[j].min(p[j]);hi[j]=hi[j].max(p[j]);}}let rx=(hi[0]-lo[0])/2.;let ry=(hi[1]-lo[1])/2.;if rx.min(ry)<10.||rx.max(ry)>5.*rx.min(ry){return None;}
 let start=vec![(lo[0]+hi[0])/2.,(lo[1]+hi[1])/2.,rx,ry];let(p,error)=optimize(start,vec![0.25;4],vec![2.;4],|p|points.iter().map(|v|sd(p,v[0],v[1]).powi(2)).sum::<f64>()/points.len() as f64);if error>0.3||points.iter().filter(|v|sd(&p,v[0],v[1]).abs()>1.).count()>points.len()/50{return None;}let area=points.windows(2).map(|v|v[0][0]*v[1][1]-v[1][0]*v[0][1]).sum::<f64>()/2.;Some(([p[0],p[1],p[2],p[3]],area))}
fn vertices(p:&[f64])->Vec<P>{(0..10).map(|i|{let a=p[4]+i as f64*std::f64::consts::PI/5.;let r=p[2]*if i%2==0{1.}else{p[3]};[p[0]+r*a.cos(),p[1]+r*a.sin()]}).collect()}
fn polygon_distance(v:&[P],p:P)->f64{let mut d=f64::INFINITY;let mut inside=false;for i in 0..v.len(){let a=v[i];let b=v[(i+1)%v.len()];let delta=[b[0]-a[0],b[1]-a[1]];let t=(((p[0]-a[0])*delta[0]+(p[1]-a[1])*delta[1])/(delta[0]*delta[0]+delta[1]*delta[1])).clamp(0.,1.);d=d.min((p[0]-a[0]-t*delta[0]).hypot(p[1]-a[1]-t*delta[1]));if (a[1]>p[1])!=(b[1]>p[1])&&p[0]<(b[0]-a[0])*(p[1]-a[1])/(b[1]-a[1])+a[0]{inside=!inside;}}if inside{-d}else{d}}
fn bilinear(a:&[f64],w:usize,h:usize,x:f64,y:f64)->f64{let base_x=x.floor()as isize;let base_y=y.floor()as isize;let kernel=|v:f64|{let t=v.abs();let alpha= -0.75;if t<=1.{(alpha+2.)*t.powi(3)-(alpha+3.)*t*t+1.}else if t<2.{alpha*t.powi(3)-5.*alpha*t*t+8.*alpha*t-4.*alpha}else{0.}};let mut result=0.;for dy in -1..=2{for dx in -1..=2{let px=base_x+dx;let py=base_y+dy;result+=a[py.clamp(0,h as isize-1)as usize*w+px.clamp(0,w as isize-1)as usize]*kernel(x-px as f64)*kernel(y-py as f64);}}result.clamp(0.,1.)}
pub fn prepare(a:&[u8],w:usize,h:usize,palette:&[[u8;3]])->Option<Plan>{
 if palette.len()!=2||w<32||h<32||w>512||h>512||a.chunks_exact(4).any(|p|p[3]!=255){return None;}
 let mut border=[0u64;2];for y in 0..h{for x in 0..w{if x==0||y==0||x==w-1||y==h-1{for k in 0..2{for j in 0..3{border[k]+=(a[4*(y*w+x)+j] as i32-palette[k][j] as i32).pow(2) as u64;}}}}}
 let bg=if border[0]<=border[1]{0}else{1};let fg=1-bg;let inks=vec![palette[bg],palette[fg]];let d:Vec<f64>=(0..3).map(|j|inks[1][j] as f64-inks[0][j] as f64).collect();let den=d.iter().map(|x|x*x).sum::<f64>();if den<6400.{return None;}
 let(mut f,mut mixtures,mut bad)=(Vec::with_capacity(w*h),0,0);for (i,p)in a.chunks_exact(4).enumerate(){let t=(0..3).map(|j|(p[j] as f64-inks[0][j] as f64)*d[j]).sum::<f64>()/den;let t=t.clamp(0.,1.);if t>0.08&&t<0.92{mixtures+=1;}if (0..3).any(|j|(p[j] as f64-inks[0][j] as f64-t*d[j]).abs()>32.){bad+=1;}let(x,y)=(i%w,i/w);if (x==0||y==0||x==w-1||y==h-1)&&t>0.1{return None;}f.push(t);}
 if mixtures<32||mixtures<w*h/1000||bad>w*h/50{return None;}
 // Enumerate closed pixel-cell contours at a permissive level, retaining thin ink evidence.
 let mut graph:HashMap<usize,Vec<usize>>=HashMap::new();let stride=w+1;let on=|x:isize,y:isize|x>=0&&y>=0&&(x as usize)<w&&(y as usize)<h&&f[y as usize*w+x as usize]>0.12;
 for y in 0..h{for x in 0..w{if !on(x as isize,y as isize){continue;}let p=y*stride+x;for(condition,s,t)in [(!on(x as isize,y as isize-1),p,p+1),(!on(x as isize+1,y as isize),p+1,p+1+stride),(!on(x as isize,y as isize+1),p+1+stride,p+stride),(!on(x as isize-1,y as isize),p+stride,p)]{if condition{graph.entry(s).or_default().push(t);}}}}
 let mut keys:Vec<_>=graph.keys().copied().collect();keys.sort_unstable();let mut candidates=Vec::new();for start in keys{while graph.get(&start).is_some_and(|v|!v.is_empty()){let mut cur=start;let mut previous=start;let mut points=Vec::new();let mut good=true;for _ in 0..w*h*4{points.push([(cur%stride) as f64,(cur/stride) as f64]);let Some(options)=graph.get_mut(&cur)else{good=false;break;};if options.is_empty(){good=false;break;}let delta=cur as isize-previous as isize;let direction=if delta==1{0}else if delta==stride as isize{1}else if delta== -1{2}else{3};let desired=(direction+3)%4;let selected=if options.len()>1{options.iter().position(|&n|{let d=n as isize-cur as isize;let q=if d==1{0}else if d==stride as isize{1}else if d== -1{2}else{3};q==desired}).unwrap_or(options.len()-1)}else{0};let next=options.remove(selected);previous=cur;cur=next;if cur==start{points.push(points[0]);break;}}if good&&points.len()>100{if let Some(e)=ellipse(&points){candidates.push(e);}}}}
 candidates.sort_by(|a,b|(a.0[2]*a.0[3]).total_cmp(&(b.0[2]*b.0[3])));let mut rings=Vec::new();let mut i=0;while i+1<candidates.len(){let(inner,ia)=candidates[i];let(outer,oa)=candidates[i+1];if ia<0.&&oa>0.&&(inner[0]-outer[0]).hypot(inner[1]-outer[1])<1.5&&outer[2]>inner[2]&&outer[3]>inner[3]&&(outer[2]/inner[2]-outer[3]/inner[3]).abs()<0.08&&(outer[2]-inner[2]).max(outer[3]-inner[3])<inner[2].min(inner[3])*0.3{
  let samples:Vec<_>=(0..w*h).filter_map(|j|{let(x,y)=((j%w)as f64+0.5,(j/w)as f64+0.5);if sd(&outer,x,y).abs()<2.||sd(&inner,x,y).abs()<2.{Some((x,y,f[j]))}else{None}}).collect();let initial:Vec<_>=outer.into_iter().chain(inner).collect();let(p,cost)=optimize(initial,vec![0.25;8],vec![1.;8],|p|{let mut cost=0.;for &(x,y,v)in &samples{let mut value=0.;for ox in [-0.375,-0.125,0.125,0.375]{for oy in [-0.375,-0.125,0.125,0.375]{value+=inside(&p[..4],x+ox,y+oy)-inside(&p[4..],x+ox,y+oy);}}cost+=(value/16.-v).powi(2);}cost/samples.len()as f64});
  if cost<0.018&&p[2]>p[6]&&p[3]>p[7]{rings.push(std::array::from_fn(|j|p[j]));i+=2;continue;}}
 i+=1;}
 // Fit isolated five-point stars only when their complete source footprint agrees.
 let mut seen=vec![false;w*h];let mut stars=Vec::new();for start in 0..w*h{if seen[start]||f[start]<0.35{continue;}let mut queue=VecDeque::from([start]);seen[start]=true;let mut points=Vec::new();while let Some(j)=queue.pop_front(){points.push(j);let(x,y)=(j%w,j/w);for (xx,yy)in [(x.wrapping_sub(1),y),(x+1,y),(x,y.wrapping_sub(1)),(x,y+1)]{if xx<w&&yy<h{let k=yy*w+xx;if !seen[k]&&f[k]>=0.35{seen[k]=true;queue.push_back(k);}}}}if points.len()<12||points.len()>200{continue;}let left=points.iter().map(|j|j%w).min().unwrap();let right=points.iter().map(|j|j%w).max().unwrap()+1;let top=points.iter().map(|j|j/w).min().unwrap();let bottom=points.iter().map(|j|j/w).max().unwrap()+1;let dx=(right-left)as f64;let dy=(bottom-top)as f64;if dx<5.||dy<5.||dx/dy<0.75||dx/dy>1.25||points.len()as f64/(dx*dy)>0.7{continue;}
 let samples:Vec<_>=(top.saturating_sub(1)..(bottom+1).min(h)).flat_map(|y|(left.saturating_sub(1)..(right+1).min(w)).map(move|x|(x,y))).map(|(x,y)|(x as f64+0.5,y as f64+0.5,f[y*w+x])).collect();let initial=vec![(left+right)as f64/2.,top as f64+dy*0.55,dy/1.8,0.4,-std::f64::consts::FRAC_PI_2];let(p,cost)=optimize(initial,vec![0.2,0.2,0.2,0.02,0.02],vec![1.,1.,1.5,0.15,0.2],|p|{let vertices=vertices(p);samples.iter().map(|&(x,y,v)|{let mut value=0.;for ox in [-0.375,-0.125,0.125,0.375]{for oy in [-0.375,-0.125,0.125,0.375]{let sd=polygon_distance(&vertices,[x+ox,y+oy]);value+=(0.5-sd*4.).clamp(0.,1.);}}(value/16.-v).powi(2)}).sum::<f64>()/samples.len()as f64});if cost<0.012{stars.push(std::array::from_fn(|j|p[j]));}}
 // No model detection, no special route: leave ordinary artwork to the general graph.
 if rings.is_empty()&&stars.is_empty(){return None;}
 let scale=8;let mut mask=vec![0;w*h*scale*scale];let star_vertices:Vec<_>=stars.iter().map(|p|vertices(p)).collect();for y in 0..h*scale{for x in 0..w*scale{let(xx,yy)=((x as f64+0.5)/scale as f64,(y as f64+0.5)/scale as f64);let mut ink=bilinear(&f,w,h,xx-0.5,yy-0.5)>0.5;for ring in &rings{if sd(&ring[..4],xx,yy)<=1.5&&sd(&ring[4..],xx,yy)>=-1.5{ink=false;}}for (v,p) in star_vertices.iter().zip(&stars){if (xx-p[0]).abs()<p[2]+2.&&(yy-p[1]).abs()<p[2]+2.&&polygon_distance(v,[xx,yy])<1.5{ink=false;}}mask[y*w*scale+x]=u8::from(ink);}}
 Some(Plan{mask,w,h,rings,stars,inks})
}
fn ellipse_path(p:&[f64])->String{let(cx,cy,rx,ry)=(p[0],p[1],p[2],p[3]);let k=0.5522847498307936;format!("M{} {} C{} {} {} {} {} {} C{} {} {} {} {} {} C{} {} {} {} {} {} C{} {} {} {} {} {} Z",cx+rx,cy,cx+rx,cy+k*ry,cx+k*rx,cy+ry,cx,cy+ry,cx-k*rx,cy+ry,cx-rx,cy+k*ry,cx-rx,cy,cx-rx,cy-k*ry,cx-k*rx,cy-ry,cx,cy-ry,cx+k*rx,cy-ry,cx+rx,cy-k*ry,cx+rx,cy)}
// Normalize once and reverse the very same primitives for the other colour.
fn paths(d:&str,scale:f64)->Option<Vec<Vec<(P,Option<[P;2]>,P)>>>{let text=d.replace('M'," M ").replace('L'," L ").replace('C'," C ").replace('Z'," Z ");let ts:Vec<_>=text.split_whitespace().collect();let(mut i,mut op)=(0,"");let(mut current,mut start)=([0.;2],[0.;2]);let mut result=Vec::new();let mut edges=Vec::new();while i<ts.len(){if matches!(ts[i],"M"|"L"|"C"|"Z"){op=ts[i];i+=1;}if op=="Z"{if current!=start{edges.push((current,None,start));}result.push(std::mem::take(&mut edges));current=start;op="";continue;}let n=if op=="C"{6}else{2};let vals:Vec<f64>=ts.get(i..i+n)?.iter().map(|s|s.parse::<f64>().ok().map(|v|(v/scale*10000.).round()/10000.)).collect::<Option<_>>()?;i+=n;let end=[vals[n-2],vals[n-1]];if op=="M"{current=end;start=end;op="L";continue;}if op!="L"&&op!="C"{return None;}edges.push((current,if op=="C"{Some([[vals[0],vals[1]],[vals[2],vals[3]]])}else{None},end));current=end;}Some(result)}
fn serialize(edges:&[(P,Option<[P;2]>,P)],reverse:bool)->String{if edges.is_empty(){return String::new();}let mut out=String::new();let start=if reverse{edges.last().unwrap().2}else{edges[0].0};write!(out,"M{:.4} {:.4} ",start[0],start[1]).unwrap();let order:Vec<_>=if reverse{edges.iter().rev().collect()}else{edges.iter().collect()};for&&(a,c,b)in &order{let end=if reverse{a}else{b};if let Some(c)=c{let(x,y)=if reverse{(c[1],c[0])}else{(c[0],c[1])};write!(out,"C{:.4} {:.4} {:.4} {:.4} {:.4} {:.4} ",x[0],x[1],y[0],y[1],end[0],end[1]).unwrap();}else{write!(out,"L{:.4} {:.4} ",end[0],end[1]).unwrap();}}out.push_str("Z ");out}
pub fn finish(plan:&Plan,d:&str)->Option<String>{let mut contours=paths(d,8.)?;let dominant=contours.iter().max_by(|a,b|{let area=|s:&Vec<(P,Option<[P;2]>,P)>|s.iter().map(|e|e.0[0]*e.2[1]-e.2[0]*e.0[1]).sum::<f64>();area(a).abs().total_cmp(&area(b).abs())});let reverse=dominant.is_some_and(|s|s.iter().map(|e|e.0[0]*e.2[1]-e.2[0]*e.0[1]).sum::<f64>()<0.);let mut fg=String::new();let mut inverse=String::new();for c in &contours{fg+=&serialize(c,reverse);inverse+=&serialize(c,!reverse);}
 for ring in &plan.rings{for(p,r)in [(&ring[..4],false),(&ring[4..],true)]{let e=paths(&ellipse_path(p),1.)?.remove(0);fg+=&serialize(&e,r);inverse+=&serialize(&e,!r);}}
 for p in &plan.stars{let v=vertices(p);let e:Vec<_>=(0..v.len()).map(|i|{let round=|p:P|p.map(|x|(x*10000.).round()/10000.);(round(v[i]),None,round(v[(i+1)%v.len()]))}).collect();fg+=&serialize(&e,false);inverse+=&serialize(&e,true);}
 let rect=format!("M0 0 L{} 0 L{} {} L0 {} Z",plan.w,plan.w,plan.h,plan.h);let background=format!("{rect} {inverse}");let outside=serialize(&paths(&rect,1.)?.remove(0),true);if !crate::shared_contract::verify(&[(0,background.clone()),(1,fg.clone()),(-1,outside)]){return None;}let color=|p:[u8;3]|format!("#{:02x}{:02x}{:02x}",p[0],p[1],p[2]);let(bg,ink)=(color(plan.inks[0]),color(plan.inks[1]));contours.clear();Some(format!("<svg xmlns=\"http://www.w3.org/2000/svg\" width=\"{}\" height=\"{}\" viewBox=\"0 0 {} {}\" data-shared-boundaries=\"true\" data-boundary-contract=\"paired\"><g fill=\"{bg}\" id=\"color-{}\"><path fill=\"{bg}\" d=\"{background}\"/></g><g fill=\"{ink}\" id=\"color-{}\"><path fill=\"{ink}\" d=\"{fg}\"/></g></svg>",plan.w,plan.h,plan.w,plan.h,&bg[1..],&ink[1..]))}
